update public.products set name='Es Buah Premium D’Lice', description='Satu jar 1 liter berisi potongan anggur Muscat dan anggur autumn, sedikit jelly anggur, mocktail pepaya yang segar dan tidak berbau pepaya, nata de coco slice, serta racikan sirup premium khas D’Lice. Porsinya melimpah dan menyegarkan untuk dinikmati bersama keluarga atau teman; satu jar cocok untuk 3–4 orang.', unit_price_idr=60000, category='fresh', display_order=10, updated_at=now() where slug='es-buah-premium';
update public.products set name='Cadbury Braid Cheese', description='Satu batang cokelat Cadbury utuh dibalut adonan pastry ala strudel berukuran besar dengan taburan keju, kemudian dipotong menjadi beberapa bagian. Perpaduan cokelat Cadbury dan pastry yang menggugah selera untuk dinikmati bersama keluarga, sahabat, atau orang tersayang.', unit_price_idr=70000, category='pastry', display_order=20, updated_at=now() where slug='cadbury-braid-cheese';
update public.products set name='Cadbury Kunafa Pistachio', description='Satu batang cokelat Cadbury utuh dengan tambahan isian cokelat Kunafa Pistachio, dibalut adonan pastry ala strudel berukuran besar dan dipotong menjadi beberapa bagian. Perpaduan cokelat Cadbury, kunafa, dan pistachio menghadirkan sensasi lebih istimewa untuk dinikmati bersama keluarga maupun teman.', unit_price_idr=90000, category='pastry', display_order=30, updated_at=now() where slug='cadbury-kunafa-pistachio-braid';
